[{"order":1,"type":"heading","text":"Cookies, Signatures, and Parsing in Express.js"},{"order":2,"type":"paragraph","text":"Web applications rely heavily on HTTP cookies to maintain state across stateless HTTP requests. In this tutorial, you will learn how to parse cookies, set them securely, and use cryptographic signatures to prevent tampering in an Express.js application."},{"order":3,"type":"heading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"To handle cookies in Express, we use the 'cookie-parser' middleware. This middleware parses the Cookie header and populates req.cookies with an object keyed by the cookie names. If a secret is provided, it also populates req.signedCookies."},{"order":5,"type":"code","text":"npm install express cookie-parser"},{"order":6,"type":"subheading","text":"Initializing the Express App"},{"order":7,"type":"paragraph","text":"Let us set up a basic Express server and mount the cookie-parser middleware with a secret key used for signing."},{"order":8,"type":"code","text":"const express = require('express');
const cookieParser = require('cookie-parser');

const app = express();
const PORT = 3000;

// Pass a secret string for signed cookies
app.use(cookieParser('my-super-secret-key'));

app.listen(PORT, () => {
  console.log('Server running on port ' + PORT);
});"},{"order":9,"heading":"Parsing and Setting Regular Cookies","type":"subheading"},{"order":10,"type":"paragraph","text":"To set a cookie on the client side, use the res.cookie() function. To read incoming cookies, access req.cookies after the cookie-parser middleware has processed the request."},{"order":11,"type":"code","text":"app.get('/set-cookie', (req, res) => {
  res.cookie('username', 'johndoe', { maxAge: 900000, httpOnly: true });
  res.send('Cookie has been set!');
});

app.get('/get-cookie', (req, res) => {
  console.log(req.cookies);
  res.send('Username cookie value: ' + req.cookies.username);
});"},{"order":12,"type":"heading","text":"Understanding Cookie Signatures"},{"order":13,"type":"paragraph","text":"Regular cookies can easily be modified by users in their browser developer tools. To ensure integrity and verify that the cookie value has not been tampered with, Express supports signed cookies."},{"order":14,"type":"bullet_point","text":"When you set a signed cookie, Express generates an HMAC using the secret key provided to 'cookie-parser'."},{"order":15,"type":"bullet_point","text":"The cookie value is appended with a dot and the signature (e.g., s:johndoe.G7v2...)."},{"order":16,"type":"bullet_point","text":"If a user alters the cookie value, the signature validation fails, and Express moves the cookie to req.unauthorizedCookies or treats it as undefined."},{"order":17,"type":"subheading","text":"Setting and Reading Signed Cookies"},{"order":18,"type":"code","text":"app.get('/set-signed-cookie', (req, res) => {
  res.cookie('userId', '98765', { signed: true, httpOnly: true });
  res.send('Signed cookie set!');
});

app.get('/get-signed-cookie', (req, res) => {
  // Access signed cookies via req.signedCookies
  const userId = req.signedCookies.userId;

  if (!userId) {
    return res.status(401).send('Tampered or missing cookie!');
  }

  res.send('Verified User ID: ' + userId);
});"},{"order":19,"type":"heading","text":"Security Best Practices"},{"order":20,"type":"bullet_point","text":"Always set 'httpOnly: true' to prevent Cross-Site Scripting (XSS) attacks from accessing document.cookie."},{"order":21,"type":"bullet_point","text":"Use 'secure: true' in production environments to ensure cookies are only transmitted over HTTPS."},{"order":22,"type":"bullet_point","text":"Implement 'sameSite: strict' or 'sameSite: lax' to mitigate Cross-Site Request Forgery (CSRF) vulnerabilities."}]
